-- OpenLedgerApp demo data for STAGING (and local development) only. Applied by
-- scripts/migrate.mjs --seed (Migrate → staging), recorded under "openledgerapp:seed",
-- so it runs once. Never on production: it refuses a database that isn't marked
-- staging by the hub, or (without the hub) one holding real organizations.
--
-- Creates the demo sign-in ledger.demo@demo.openapphub.org (password demo1234, demo use only) and
-- its two sample organizations, Acme Demo Co and Riverside Community Kitchen, as core
-- organizations it owns, with their books in schema ledger.
do $$
begin
  if to_regclass('hub.instance') is not null then
    if coalesce((select environment from hub.instance where id), '') <> 'staging' then
      raise exception 'Refusing to seed: this database is not marked staging.';
    end if;
  elsif exists (select 1 from public.organizations where id::text not like 'd0e00000-%') then
    raise exception 'Refusing to seed: this database has real organizations.';
  end if;
end $$;

-- Demo sign-in. Token columns must be '' (not null) for sign-in to work. Triggers run,
-- so core gives it a profile.
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current,
  reauthentication_token, phone_change, phone_change_token)
values ('00000000-0000-0000-0000-000000000000', 'd0e00000-0000-0000-0000-000000000003', 'authenticated', 'authenticated', 'ledger.demo@demo.openapphub.org',
  extensions.crypt('demo1234', extensions.gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}', '{"full_name":"Ledger Demo"}', now(), now(),
  '', '', '', '', '', '', '', '')
on conflict (id) do nothing;
values ('d0e00000-0000-0000-0000-000000000003', 'd0e00000-0000-0000-0000-000000000003', jsonb_build_object('sub', 'd0e00000-0000-0000-0000-000000000003', 'email', 'ledger.demo@demo.openapphub.org', 'email_verified', true),
  'email', now(), now(), now())
on conflict do nothing;

-- Core organizations (triggers run: billing trial, exactly one owner).
-- On the hub's database, mark them demo organizations (a long trial; the hub lists them).
do $$
begin
  if to_regclass('hub.demo_orgs') is not null then
    execute $q$insert into hub.demo_orgs (org_id, created_by) values
      ('d0e00000-0000-0000-0000-000000000002', 'd0e00000-0000-0000-0000-000000000003'),
      ('d0e00000-0000-0000-0000-000000000004', 'd0e00000-0000-0000-0000-000000000003')
      on conflict do nothing$q$;
  end if;
end $$;

-- The books, captured from the old demo. Triggers are skipped so already-reconciled
-- rows load exactly as captured.
set local session_replication_role = replica;
set local session_replication_role = origin;
